    emailHtml: "<!DOCTYPE html>\n<html>\n<head>\n    <style>\n        body { background-color: #fbfbf9; color: #11131f; font-family: 'Segoe UI', Tahoma, sans-serif; line-height: 1.6; margin: 0; padding: 0; }\n        .container { max-width: 600px; margin: 20px auto; background: #ffffff; border-top: 8px solid #df8431; border-bottom: 4px solid #11131f; }\n        .header { padding: 30px 40px 10px 40px; }\n        .header h2 { color: #11131f; margin: 0; }\n        .content { padding: 10px 40px 30px 40px; font-size: 16px; }\n        .footer { padding: 20px 40px; background-color: #11131f; color: #fbfbf9; font-size: 12px; text-align: center; }\n        .button { display: inline-block; padding: 14px 28px; background: #df8431; color: #ffffff; text-decoration: none; border-radius: 4px; font-weight: bold; margin: 20px 0; }\n        .alert-box { background-color: #fff5f5; border-left: 4px solid #df8431; padding: 15px 20px; margin: 20px 0; border-radius: 0 4px 4px 0; }\n    </style>\n</head>\n<body>\n    <div class=\"container\">\n        <div class=\"header\"><h2>Here's your receipt</h2></div>\n        <div class=\"content\">\n            <p>Hi {{kinfolkName}}, thank you! This is your receipt for invoice {{invoiceNumber}}, paid in full at {{amount}}.</p>\n            <p>Keep it for your records. I appreciate you.</p>\n            <p>With thanks,<br><strong>Auntie</strong></p>\n        </div>\n        <div class=\"footer\">Tribe Tails Pet Care. Your Kin's Favorite Auntie.</div>\n    </div>\n</body>\n</html>\n",
    emailTxt: "Subject: Here's your receipt\n\nHi {{kinfolkName}}, thank you! This is your receipt for invoice {{invoiceNumber}}, paid in full at {{amount}}.\n\nKeep it for your records. I appreciate you.\n\nWith thanks, Auntie\n\nTribe Tails Pet Care. Your Kin's Favorite Auntie.\n",
    smsTxt: "It's Auntie. Your receipt for invoice {{invoiceNumber}} ({{amount}}, paid in full) is ready.\n",
    pushTxt: "Your receipt is ready. Invoice {{invoiceNumber}} is paid in full. Tap to view your receipt.\n",
